sys_script.script:
(function executeRule(current, previous) {
    var category = current.getValue('pool_category');
    var base = current.getValue('applies_to_base');

    if (!category || !base) {
        return;
    }

    // Valid combinations: category → allowed base
    var validMap = {
        'labor_burden': 'total_direct_labor',
        'material_burden': 'total_direct_material',
        'subcontract_burden': 'total_subcontract'
    };

    var expectedBase = validMap[category];
    if (expectedBase && base !== expectedBase) {
        var categoryLabels = {
            'labor_burden': 'Labor Burden',
            'material_burden': 'Material Burden',
            'subcontract_burden': 'Subcontract Burden'
        };
        var baseLabels = {
            'total_direct_labor': 'Total Direct Labor',
            'total_direct_material': 'Total Direct Material',
            'total_subcontract': 'Total Subcontract'
        };
        gs.addErrorMessage(
            'Invalid combination: Pool category "' + categoryLabels[category] +
            '" must apply to base "' + baseLabels[expectedBase] +
            '", not "' + (baseLabels[base] || base) + '".'
        );
        current.setAbortAction(true);
    }
})(current, previous);
